t.script:
(function () {
    const root = document.currentScript.closest('.o_carousel_product_indicators');
    if (!root) {
        return;
    }

    const thumbCarouselEl = root.querySelector('#o-carousel-product-thumb-carousel');
    const mainCarouselEl = document.getElementById('o-carousel-product');
    if (!thumbCarouselEl || !mainCarouselEl) {
        return;
    }

    const thumbButtons = Array.from(root.querySelectorAll('.o_thumb_btn[data-thumb-index]'));
    if (!thumbButtons.length) {
        return;
    }

    const mainSlides = Array.from(mainCarouselEl.querySelectorAll('.carousel-item'));
    if (!mainSlides.length) {
        return;
    }

    const bootstrapCarousel = window.bootstrap && window.bootstrap.Carousel;
    const mainCarousel = bootstrapCarousel ? bootstrapCarousel.getOrCreateInstance(mainCarouselEl) : null;
    let thumbCarousel = null;

    const thumbSlides = Array.from(thumbCarouselEl.querySelectorAll('.carousel-item'));
    if (bootstrapCarousel && thumbSlides.length > 1) {
        thumbCarousel = bootstrapCarousel.getOrCreateInstance(thumbCarouselEl, { interval: false, ride: false, wrap: false });
    }

    let pendingZoomIndex = null;

    const getActiveIndex = () => {
        const activeItem = mainCarouselEl.querySelector('.carousel-item.active');
        const index = mainSlides.indexOf(activeItem);
        return index === -1 ? 0 : index;
    };

    function findZoomTrigger() {
        const activeSlide = mainCarouselEl.querySelector('.carousel-item.active');
        if (!activeSlide) {
            return null;
        }
        return activeSlide.querySelector('[data-oe-lightbox], [data-zoomodoo], [data-oe-media-url]')
            || activeSlide.querySelector('a, button');
    }

    function openZoomIfAvailable() {
        const trigger = findZoomTrigger();
        if (trigger && typeof trigger.click === 'function') {
            trigger.click();
        }
    }

    function ensureThumbVisible(targetIndex) {
        if (!thumbCarousel) {
            return;
        }
        const activeButton = thumbButtons.find(btn => Number(btn.dataset.thumbIndex) === targetIndex);
        if (!activeButton) {
            return;
        }
        const parentSlide = activeButton.closest('.carousel-item');
        const slideIndex = thumbSlides.indexOf(parentSlide);
        if (slideIndex > -1 && !parentSlide.classList.contains('active')) {
            thumbCarousel.to(slideIndex);
        }
    }

    function setActiveThumb(targetIndex) {
        thumbButtons.forEach(btn => {
            btn.classList.toggle('active', Number(btn.dataset.thumbIndex) === targetIndex);
        });
        ensureThumbVisible(targetIndex);
    }

    function handleSlideChange(index) {
        setActiveThumb(index);
        if (pendingZoomIndex !== null && pendingZoomIndex === index) {
            openZoomIfAvailable();
        }
        pendingZoomIndex = null;
    }

    thumbButtons.forEach(btn => {
        btn.addEventListener('click', (ev) => {
            ev.preventDefault();
            const targetIndex = Number(btn.dataset.thumbIndex);
            if (Number.isNaN(targetIndex)) {
                return;
            }
            const currentIndex = getActiveIndex();
            pendingZoomIndex = targetIndex;
            if (mainCarousel) {
                if (currentIndex === targetIndex) {
                    handleSlideChange(targetIndex);
                } else {
                    mainCarousel.to(targetIndex);
                }
            } else if (window.jQuery && typeof jQuery(mainCarouselEl).carousel === 'function') {
                if (currentIndex === targetIndex) {
                    handleSlideChange(targetIndex);
                } else {
                    jQuery(mainCarouselEl).carousel(targetIndex);
                }
            } else {
                mainSlides.forEach((item, idx) => {
                    item.classList.toggle('active', idx === targetIndex);
                });
                handleSlideChange(targetIndex);
            }
        });
    });

    mainCarouselEl.addEventListener('slid.bs.carousel', (ev) => {
        const newIndex = typeof ev.to === 'number' ? ev.to : getActiveIndex();
        handleSlideChange(Number.isNaN(newIndex) ? getActiveIndex() : newIndex);
    });

    if (window.jQuery && typeof jQuery(mainCarouselEl).on === 'function') {
        jQuery(mainCarouselEl).on('slid.bs.carousel', () => {
            handleSlideChange(getActiveIndex());
        });
    }

    setActiveThumb(getActiveIndex());
})();
